     3	/**
     4	 * Valid datacenter-code per provider, plus a human-readable label for each.
     5	 * `Node.region` is a plain string (not an enum) because datacenter codes
     6	 * grow far more often than providers do — same "fast-changing categorical
     7	 * value, validated in code not the DB" convention this schema already uses
     8	 * for StaffGrant.area (see lib/staff-grants.ts). Validate any new/edited
     9	 * Node's region against `NODE_REGIONS[provider]` rather than trusting a
    10	 * free-typed string from the admin form.
    11	 *
    12	 * Codes are each provider's OWN real datacenter code (OVH's/Hetzner's own
    13	 * naming), not a platform-invented scheme — "sgp1" (OVH Singapore, where the
    14	 * primary node actually is — confirmed via geoip-lite against its live
    15	 * public IP, not guessed) and "fsn1" (Hetzner Falkenstein, Germany, the new
    16	 * node) are both real. The other codes below are real provider datacenter
    17	 * codes too, listed so the region field has somewhere to grow without a
    18	 * schema change — add more here as real nodes are added, not speculatively.
    19	 */
    20	export const NODE_REGIONS = {
    21	  OVH: ["sgp1", "bhs1", "gra1", "rbx1", "waw1"],
    22	  HETZNER: ["fsn1", "nbg1", "hel1", "ash1", "hil1"],
    23	} as const satisfies Record<NodeProvider, readonly string[]>;
    24	
    25	/** Every valid region code, derived from `NODE_REGIONS`. */
    26	export type RegionCode = (typeof NODE_REGIONS)[keyof typeof NODE_REGIONS][number];
    27	
    28	/**
    29	 * `REGION_LABELS` / `CUSTOMER_REGION_LABELS` / `REGION_COUNTRY` /
    30	 * `REGION_COORDS` below are each built as a `_STRICT` const first, checked
    31	 * with `satisfies Record<RegionCode, ...>` so `npx tsc --noEmit` fails if a
    32	 * future region is added to `NODE_REGIONS` without a matching entry in every
    33	 * one of these tables (a missing OR a stray/misspelled key both fail the
    34	 * check) — then exported at the wider `Record<string, ...>` type every
    35	 * existing call site already expects (`REGION_COUNTRY[region] ?? fallback`
    36	 * with `region: string` straight off a DB row), so this hardening needed no
    37	 * changes anywhere else in the codebase.
    38	 *
    39	 * Added 2026-09-29 during the Canada/bhs1 rollout audit. Nothing here was
    40	 * actually found missing an entry for bhs1 — `REGION_COUNTRY` has had
    41	 * `bhs1: "ca"` since this file was first created, well before the Canada
    42	 * node existed — but the audit did find a SECOND, hand-copied region table
    43	 * in components/admin/NodeForms.tsx (a client component that didn't need to
    44	 * duplicate this at all — this file has no `server-only` import, so it can
    45	 * be imported directly into a client component) that had nothing keeping it
    46	 * in sync with this one. A duplicated, hand-maintained table is exactly the
    47	 * shape of bug that WOULD silently ship a wrong flag/label for the next new
    48	 * region, so that duplicate was deleted (NodeForms.tsx now imports straight
    49	 * from here) and this file was hardened so the same class of drift can't
    50	 * reappear inside it either.
    51	 */
    52	const REGION_LABELS_STRICT = {
    53	  sgp1: "Singapore",
    54	  bhs1: "Beauharnois, CA",
    55	  gra1: "Gravelines, FR",
