   108	export function isValidRegion(provider: NodeProvider, region: string): boolean {
   109	  // NODE_REGIONS' values are readonly literal-string tuples (see the comment
   110	  // above it) so `.includes` narrows its argument to that literal union;
   111	  // `region` here is deliberately a plain, untrusted `string` (admin form
   112	  // input), so it's cast back to check membership rather than typed.
   113	  return (NODE_REGIONS[provider] as readonly string[])?.includes(region) ?? false;
