/**
 * Self-serve cross-region transfer — pure rules (growth item prd-016).
 *
 * THE CUSTOMER FEATURE ONLY CREATES A REQUEST. The VM move engine is NO-GO for
 * real customers until its rehearsals are done (docs/VM-MOVE-DEEP-ANALYSIS.md),
 * so nothing here moves anything: an admin reviews each request and, when the
 * engine is cleared, runs the move from the server's Move tab. The whole
 * customer surface is behind Setting region_transfer_enabled (default off).
 *
 * The downtime figure is an ESTIMATE, labelled as one, banded by how much the
 * server stores and taken from the two manual transfers support has done
 * (30-45 minutes for a small world; 3-6 hours for a heavy one — tickets 1 and
 * 9). It is not a measurement and the engine has produced no real timings yet.
 */

export const TRANSFER_STATUSES = ["REQUESTED", "APPROVED", "REJECTED", "CANCELLED", "COMPLETED"] as const;
export type TransferStatus = (typeof TRANSFER_STATUSES)[number];
/** Requests in these states block a new one for the same server. */
export const OPEN_STATUSES: TransferStatus[] = ["REQUESTED", "APPROVED"];

export type Estimate = { label: string; maxMinutes: number | null; basis: string };

/** Band by used storage (GB). `null` size = unknown: say so, give the full range. */
export function estimateDowntime(usedGb: number | null): Estimate {
  const basis = "Estimate based on the transfers our team has done by hand. We confirm a time with you before anything moves.";
  if (usedGb == null || !Number.isFinite(usedGb) || usedGb < 0) {
    return { label: "30 minutes to a few hours, depending on how much your server stores", maxMinutes: null, basis };
  }
  if (usedGb < 5) return { label: "about 30 to 60 minutes", maxMinutes: 60, basis };
  if (usedGb < 20) return { label: "about 1 to 2 hours", maxMinutes: 120, basis };
  return { label: "about 2 to 6 hours", maxMinutes: 360, basis };
}

