const execFileP = promisify(execFile);

/**
 * Is this address already the target of a live DNAT rule on ITS OWN node?
 * Some infrastructure (the shared-hosting node, VM 200) reaches its dedicated
 * IP entirely through a whole-IP DNAT rule to an internal address — it has no
 * OVH Virtual MAC at all, so the MAC-based check above cannot see it. A real
 * incident: this exact IP was one query away from being handed to a game
 * server because "no Virtual MAC bound" was mistaken for "free" — it was
 * actively carrying production hosting traffic via `iptables -t nat`. Treat
 * any address with a live DNAT target as claimed, unconditionally.
 *
 * Dispatches by node: the primary's own local iptables (unchanged), or the
 * owning node's agent for anyone else — this used to always check the LOCAL
 * host regardless of which node `address` actually belongs to, which for a
 * non-primary node's pool checks the wrong machine's kernel entirely and
 * could double-allocate an address that's actually already claimed there.
 */
async function hasLiveDnatRule(node: NodeRow, address: string): Promise<boolean> {
  if (!node.isPrimary) {
    try {
      return await agentHasLiveDnatRule(node, address);
    } catch {
      // Agent unreachable/not configured — same fail-open reasoning as the
      // local case below: a false "not claimed" is recoverable (the Virtual
      // MAC check and the existing DB row are the other guards), a sync that
      // silently no-ops for an entire node's pool forever is not.
      return false;
    }
  }
  try {
    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
  } catch {
    // iptables unreadable (permissions, not present, sandboxed test env) — fail
    // closed is wrong here (it would make every sync a no-op); fail to "not
    // claimed by this specific check" and rely on the Virtual MAC check plus
    // the existing DB row remaining authoritative for anything already tracked.
    return false;
  }
}

