/** OVH failover gateway = the host's /24 gateway (…​.254). OVH-specific — every
 *  additional/failover IP on an OVH dedicated server shares this one convention. */
function ovhGatewayFor(nodePublicIp: string): string {
  const parts = nodePublicIp.split(".");
  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
}

/** Back-compat wrapper for any caller still expecting the old single-node signature. */
export function ovhGateway(): string {
  return ovhGatewayFor(process.env.PUBLIC_IP ?? "51.79.162.96");
}

