async function resolveNode(nodeId?: string): Promise<NodeRow | null> {
  if (nodeId) {
    return db.node.findUnique({ where: { id: nodeId }, select: NODE_ROW_SELECT });
  }
  return db.node.findFirst({ where: { isPrimary: true }, select: NODE_ROW_SELECT });
