  }
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    throw new DedicatedIpPurchaseError("Server is busy — wait for the current operation to finish.");
  }
  if (!server.vmid) throw new DedicatedIpPurchaseError("This server hasn't finished provisioning yet.");

  // A DB-level check only — the authoritative claim happens atomically in the
  // worker (allocateDedicatedIp). This just avoids charging a customer for a
  // pool we already know is empty.
  const available = await freeCount();
  if (available <= 0) {
    throw new DedicatedIpPurchaseError(
      "No dedicated IPs are available in the pool right now — please contact support and we'll get one allocated.",
    );
  }

  const monthlyCents = await dedicatedIpMonthlyCents();
  let prorateCents = 0;
  if (!server.isFree && server.expiresAt) {
    // Reuses the generic "flat monthly amount × remaining months" prorate
    // formula lib/extra-disk.ts already owns for the disk add-on — it is not
    // disk-specific despite the name (`Math.max(0, Math.round(monthly * months))`),
    // and this is exactly the shape of a flat monthly surcharge like the
    // dedicated-IP price, so it is reused rather than redefined a third time.
    prorateCents = extraDiskProrateCents(monthlyCents, remainingMonths(server.expiresAt, Date.now()));
