/**
 * Which Proxmox template VMIDs each node actually has — so the scheduler never
 * places an order on a node that cannot clone its image.
 *
 * WHY (2026-10-01, audit P): templates are per node (the fleet is 5
 * non-clustered Proxmox installs) and they are NOT uniform: node-2 and node-4
 * lack 9005-9009, node-5 lacks 9001 and 9005-9009 — yet all three accept
 * provisions, and scheduleNode() picked purely on RAM. An order for, say,
 * Debian 13 / Webmin / HestiaCP / CloudPanel (9001) landing on node-5 was
 * charged, then failed at `qm clone` with a Proxmox error the customer saw as a
 * failed deploy.
 *
 * Read-only: one `GET /nodes/<node>/qemu` per node, cached in-process for
 * TEMPLATE_CACHE_TTL_MS. A node whose list cannot be read is treated as NOT
 * having the template (fail closed) and reported once per cache window.
 */
import { pveFor } from "./proxmox";
import { logError } from "./log";

export const TEMPLATE_CACHE_TTL_MS = 10 * 60_000;

type NodeLike = { id: string; name: string; apiUrl: string; pveNode: string; tokenId: string; tokenSecret: string };

const cache = new Map<string, { at: number; vmids: Set<number> | null }>();

/** Pure: template vmids out of a `GET /nodes/<node>/qemu` listing. */
export function templateVmidsFromListing(list: unknown): Set<number> {
  const out = new Set<number>();
  if (!Array.isArray(list)) return out;
  for (const v of list) {
    const vmid = Number((v as any)?.vmid);
    if (Number.isInteger(vmid) && String((v as any)?.template ?? "") === "1") out.add(vmid);
  }
  return out;
}

/** Template vmids on one node, or null when the node's API could not be read. */
export async function nodeTemplateVmids(node: NodeLike, now = Date.now()): Promise<Set<number> | null> {
  const hit = cache.get(node.id);
  if (hit && now - hit.at < TEMPLATE_CACHE_TTL_MS) return hit.vmids;
  let vmids: Set<number> | null = null;
  try {
    const conn = pveFor({ apiUrl: node.apiUrl, pveNode: node.pveNode, tokenId: node.tokenId, tokenSecret: node.tokenSecret });
    vmids = templateVmidsFromListing(await conn.get(`/nodes/${node.pveNode}/qemu`));
  } catch (e) {
    logError("node-templates", e, { node: node.name, note: "could not list templates; node excluded from scheduling for this window" });
  }
  cache.set(node.id, { at: now, vmids });
  return vmids;
}

